import{_ as l,C as s,o as d,c as e,j as i,a as t,E as n,a2 as r}from"./chunks/framework.C21TwvGF.js";const X=JSON.parse(`{"title":"2-dars (Mentor). UX/UI dizayn tamoyillari va jarayoni: yaxshi dizayn qanday bo'ladi","description":"","frontmatter":{"title":"2-dars (Mentor). UX/UI dizayn tamoyillari va jarayoni: yaxshi dizayn qanday bo'ladi","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (UX/UI)","link":"/mentor/9-sinf/"},"week":{"n":1,"link":"/mentor/9-sinf/hafta-01/"},"g":2,"title":"UX/UI dizayn tamoyillari va jarayoni: yaxshi dizayn qanday bo'ladi","lead":"Nega bir ilovani «o'zi tushunarli» deymiz, boshqasida esa adashib qolamiz? Bugun yaxshi dizaynni ajratadigan aniq qoidalarni (4C va 7 ta UX tamoyili) va dizayn qanday bosqichlardan o'tishini o'rganamiz.","slide":"/slaydlar/9-sinf/hafta-01/dars-2.html","test":"/slaydlar/9-sinf/hafta-01/dars-2-test.html","student_link":"/9-sinf/hafta-01/dars-2","tabs":[{"g":1,"link":"/mentor/9-sinf/hafta-01/dars-1","current":false},{"g":2,"link":"/mentor/9-sinf/hafta-01/dars-2","current":true},{"g":3,"link":"/mentor/9-sinf/hafta-01/dars-3","current":false}],"prev":{"g":1,"title":"UX va UI dizayn tushunchalari: nima va nima uchun","link":"/mentor/9-sinf/hafta-01/dars-1"},"next":{"g":3,"title":"Foydalanuvchi tadqiqotlari: nega, qanday usullar va persona","link":"/mentor/9-sinf/hafta-01/dars-3"}}},"headers":[],"relativePath":"mentor/9-sinf/hafta-01/dars-2.md","filePath":"mentor/9-sinf/hafta-01/dars-2.md"}`),h={name:"mentor/9-sinf/hafta-01/dars-2.md"},m={class:"blk"},y={id:"_1-dars-rejasi",tabindex:"-1"},u={class:"blk"},g={id:"_2-konspekt",tabindex:"-1"},b={class:"blk"},k={id:"_3-namuna-materiallar-kod-o-rniga",tabindex:"-1"},q={class:"blk"},v={id:"_4-amaliy-topshiriqlar",tabindex:"-1"},f={class:"blk"},z={id:"_5-tezkor-nazorat",tabindex:"-1"},c={class:"blk"},p={id:"_6-uyga-vazifa",tabindex:"-1"},x={class:"blk"},_={id:"_7-mentor-uchun-eslatmalar",tabindex:"-1"};function C(U,a,j,T,I,M){const o=s("Icon");return d(),e("div",null,[a[21]||(a[21]=i("p",null,[i("strong",null,"Hafta:"),t(" 1 · "),i("strong",null,"Davomiyligi:"),t(" 80 daqiqa · "),i("strong",null,"Turi:"),t(" nazariya + amaliyot (qog'ozda, kompyutersiz ham bo'ladi) · "),i("strong",null,"I-bob"),t(", 2-dars")],-1)),a[22]||(a[22]=i("blockquote",null,[i("p",null,[t("Dasturda «UX va UI dizayn tushunchalari» mavzusiga 2 dars ajratilgan (1–2). Bo'linish: 1-dars — UX va UI nima va ularning farqi (boshqa fayl); "),i("strong",null,"2-dars (shu dars)"),t(" — UI ning 4C tamoyili, UX ning 7 tamoyili, yaxshi va yomon dizayn belgilari, dizayn jarayoni (wireframe, mockup, prototip), foydalanuvchi kim. 3-dars — foydalanuvchi tadqiqoti usullari. Manba: o'quv qo'llanma, 1.1 bo'lim.")])],-1)),i("div",m,[i("h2",y,[n(o,{name:"file-text"}),a[0]||(a[0]=t(" 1. Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars rejasi"'},"​",-1))]),a[2]||(a[2]=r('<p><strong>Maqsad:</strong> o&#39;quvchi tayyor ilovani 4C va UX tamoyillari bo&#39;yicha baholaydi, dizayn jarayonining bosqichlarini va wireframe / mockup / prototip farqini biladi, «foydalanuvchi kim?» savoli nega birinchi turishini tushunadi.</p><p><strong>Kutiladigan natija:</strong></p><ul><li>UI ning 4C tamoyilini (Control, Consistency, Comfortability, Cognitive Load) misol bilan tushuntiradi.</li><li>UX ning 7 tamoyilini sanaydi va har biriga bitta real misol topadi.</li><li>Yaxshi va yomon interfeysni ajratadigan belgilarni (checklist) aytadi.</li><li>Wireframe, mockup va prototipni bir-biridan farqlaydi, jarayon tartibini biladi.</li><li>Foydalanuvchi (persona), uning maqsadi va user flow nima ekanini oddiy tilda aytadi.</li></ul><table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>0–10</td><td>Takrorlash</td><td>1-dars: UX nima, UI nima, farqi; blits-savollar</td></tr><tr><td>10–25</td><td>Yangi mavzu 1</td><td>Yaxshi / yomon dizayn belgilari; UI 4C</td></tr><tr><td>25–40</td><td>Yangi mavzu 2</td><td>UX ning 7 tamoyili, misollar</td></tr><tr><td>40–45</td><td>Tanaffus</td><td></td></tr><tr><td>45–58</td><td>Yangi mavzu 3</td><td>Dizayn jarayoni, wireframe / mockup / prototip; foydalanuvchi kim, user flow</td></tr><tr><td>58–76</td><td>Amaliyot</td><td>Mini-audit va yomon ekranni qayta chizish</td></tr><tr><td>76–80</td><td>Tezkor nazorat va xulosa</td><td>3-darsga ko&#39;prik</td></tr></tbody></table>',4))]),i("div",u,[i("h2",g,[n(o,{name:"file-text"}),a[3]||(a[3]=t(" 2. Konspekt ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-konspekt","aria-label":'Permalink to "<Icon name="file-text" /> 2. Konspekt"'},"​",-1))]),a[5]||(a[5]=r('<h3 id="_2-1-takrorlash-10-daqiqa" tabindex="-1">2.1. Takrorlash (10 daqiqa) <a class="header-anchor" href="#_2-1-takrorlash-10-daqiqa" aria-label="Permalink to &quot;2.1. Takrorlash (10 daqiqa)&quot;">​</a></h3><p>1-darsni qisqa qaytaring (savollar mentor ixtiyorida, 1-dars materiali bilan moslang): UX nima? UI nima? «Google Maps da xarita, tugma va menyular qaysi biriga kiradi?» (UI.) «Ilovada maqsadingizga tez erishdingizmi yoki adashdingizmi — bu nima?» (UX.) Jadval: UI — tashqi ko&#39;rinish (ranglar, tugmalar, shriftlar); UX — umumiy tajriba (qulaylik, tezlik, his-tuyg&#39;u). Ko&#39;prik: «Bugun «yaxshi» dizaynni qanday aniq mezon bilan ajratishni o&#39;rganamiz».</p><h3 id="_2-2-yaxshi-va-yomon-dizayn-oddiy-belgilar" tabindex="-1">2.2. Yaxshi va yomon dizayn: oddiy belgilar <a class="header-anchor" href="#_2-2-yaxshi-va-yomon-dizayn-oddiy-belgilar" aria-label="Permalink to &quot;2.2. Yaxshi va yomon dizayn: oddiy belgilar&quot;">​</a></h3><p>Manbada «yaxshi/yomon» ro&#39;yxati bevosita berilmagan; quyidagi belgilar qo&#39;llanmadagi tamoyillardan (4C va UX tamoyillari) kelib chiqadi. O&#39;quvchiga shunday ayting: «Tamoyil — qoida, belgi — shu qoida buzilganda ko&#39;zga tashlanadigan alomat.»</p><table tabindex="0"><thead><tr><th>Yomon dizayn belgisi</th><th>Yaxshi dizayn belgisi</th><th>Qaysi tamoyil</th></tr></thead><tbody><tr><td>Ekranda ortiqcha bezak va ma&#39;lumot, ko&#39;z adashadi</td><td>Faqat kerakli narsa, bitta asosiy harakat</td><td>Cognitive Load, Simplicity</td></tr><tr><td>Tugma bosildi, lekin hech narsa o&#39;zgarmadi</td><td>Bosishga javob bor: rang, yuklanish, xabar</td><td>Feedback</td></tr><tr><td>Xato qildingiz, qaytarib bo&#39;lmaydi</td><td>«Bekor qilish» va «Orqaga» bor</td><td>Control</td></tr><tr><td>Har sahifada tugmalar har xil</td><td>Tugmalar, ranglar bir xil mantiqda</td><td>Consistency</td></tr><tr><td>Yozuv mayda, tugmalar bir-biriga yopishgan</td><td>O&#39;qish oson, masofalar yetarli</td><td>Comfortability</td></tr><tr><td>Nima qilishni tushuntirish kerak</td><td>O&#39;zi tushunarli (intuitiv)</td><td>Usability</td></tr></tbody></table><p>Qoida: «<strong>Foydalanuvchi qo&#39;llanma o&#39;qimasdan ishlata olsa — dizayn yaxshi.</strong>»</p><h3 id="_2-3-ui-dizaynning-4c-tamoyili" tabindex="-1">2.3. UI dizaynning 4C tamoyili <a class="header-anchor" href="#_2-3-ui-dizaynning-4c-tamoyili" aria-label="Permalink to &quot;2.3. UI dizaynning 4C tamoyili&quot;">​</a></h3><p>UI dizaynning asosiy tamoyillaridan biri — to&#39;rtta C:</p><ol><li><strong>Control (Nazorat).</strong> Foydalanuvchi interfeysni boshqara olishi, harakatlari natijasini nazorat qilishi kerak. Misol: «Bekor qilish (Undo)» va «Orqaga (Back)» — xatoni tuzatish imkonini beradi, ishonch va qulaylikni oshiradi.</li><li><strong>Consistency (Izchillik).</strong> Tugmalar, ranglar, belgilar, menyular bir xil mantiq va uslubda. Foydalanuvchi tez moslashadi, yangi funksiyani tez tushunadi.</li><li><strong>Comfortability (Qulaylik).</strong> Ish jarayoni tabiiy, oddiy, stresssiz: elementlar qulay joylashgan, masofa optimal, yozuv o&#39;qishga oson.</li><li><strong>Cognitive Load (Kognitiv yuklanish).</strong> Ortiqcha ma&#39;lumot, bezak va matn bilan charchatmaslik. Har sahifada foydalanuvchi kerakli narsani tez topishi kerak. O&#39;xshatish: «sumkaga faqat kerakli narsani soling; hammasini solsangiz, hech narsani topolmaysiz».</li></ol><p><em>Eslatma:</em> «Consistency» UX tamoyillarida ham bor (2.4); bu atayin, bir g&#39;oya ikki tomondan: UI da ko&#39;rinish izchilligi, UX da mantiq izchilligi.</p><h3 id="_2-4-ux-dizaynning-asosiy-tamoyillari-7-ta" tabindex="-1">2.4. UX dizaynning asosiy tamoyillari (7 ta) <a class="header-anchor" href="#_2-4-ux-dizaynning-asosiy-tamoyillari-7-ta" aria-label="Permalink to &quot;2.4. UX dizaynning asosiy tamoyillari (7 ta)&quot;">​</a></h3><ol><li><strong>User-Centered Design (foydalanuvchi markazida).</strong> Dizaynning barcha bosqichlari foydalanuvchi ehtiyoji, maqsadi va odatini hisobga oladi.</li><li><strong>Usability &amp; Intuitiveness (qulaylik va intuitivlik).</strong> Qo&#39;shimcha tushuntirishsiz, tabiiy ishlata olish.</li><li><strong>Consistency (izchillik).</strong> Elementlar har sahifada bir xil mantiqda; orientatsiya osonlashadi.</li><li><strong>Simplicity &amp; Clarity (oddiylik va aniqlik).</strong> Ortiqcha bezaksiz; har element maqsadli.</li><li><strong>Feedback (fikr-mulohaza).</strong> Har bir amalga tizim javob qaytaradi: tugma rangi o&#39;zgaradi, xabar chiqadi.</li><li><strong>Flexibility &amp; Accessibility (moslashuvchanlik).</strong> Turli ekran, qurilma va imkoniyatlarga (jumladan nogironlar uchun) mos.</li><li><strong>Testing &amp; Iteration (testlash va takomillashtirish).</strong> Dizayn doimiy sinov va foydalanuvchi fikri asosida yaxshilanadi; bu hech qachon «tugamaydi».</li></ol><p>Real misollar (qo&#39;llanmadan va o&#39;quvchiga tanish): Google Maps (xarita, tugmalar, menyular: UI; manzilga yetib borish: UX); kiyim-kechak saytida toifalarga bo&#39;lish (axborot arxitekturasi); ijtimoiy tarmoq ilovasi (foydalanuvchi qaysi funksiyani ko&#39;proq qadrlashini o&#39;rganish); «Mobile_Book» ilovasi (qidiruv, ro&#39;yxat, tafsilot, yuklab olish). Mentor o&#39;zi Telegram, Instagram, maktab sayti misollarini qo&#39;shishi mumkin: bular manbada yo&#39;q, shuning uchun «bizning kuzatuvimiz» deb ayting.</p><h3 id="_2-5-dizayn-jarayoni-g-oyadan-tayyor-mahsulotgacha" tabindex="-1">2.5. Dizayn jarayoni: g&#39;oyadan tayyor mahsulotgacha <a class="header-anchor" href="#_2-5-dizayn-jarayoni-g-oyadan-tayyor-mahsulotgacha" aria-label="Permalink to &quot;2.5. Dizayn jarayoni: g&#39;oyadan tayyor mahsulotgacha&quot;">​</a></h3><p>Qo&#39;llanma bo&#39;yicha UX dizayner ishi: foydalanuvchi tadqiqoti → axborot arxitekturasi → wireframe va prototip → foydalanuvchi testi → iterativ takomillashtirish. Metodologiya sifatida <strong>Design Thinking</strong>: Empatiya → Muammo → G&#39;oya → Prototip → Test. Qo&#39;shimcha: <strong>Lean UX</strong> («avval sinab ko&#39;r, keyin tuzat») va <strong>Agile UX</strong> (jamoa qisqa sprintlarda ishlaydi).</p><p>Uch tushuncha:</p><table tabindex="0"><thead><tr><th></th><th>Aniqlik</th><th>Interaktivmi?</th><th>Maqsadi</th></tr></thead><tbody><tr><td><strong>Wireframe</strong></td><td>past: kulrang shakllar, tuzilish</td><td>yo&#39;q</td><td>joylashuv, struktura, oqim (skelet)</td></tr><tr><td><strong>Mockup (maket)</strong></td><td>yuqori: rang, shrift, ikon</td><td>yo&#39;q (statik)</td><td>yakuniy ko&#39;rinishni tasavvur qilish</td></tr><tr><td><strong>Prototip</strong></td><td>past yoki yuqori</td><td><strong>ha</strong>: tugma bosiladi, sahifa almashadi</td><td>UX ni tekshirish, test</td></tr></tbody></table><p>Prototip yaratish bosqichlari (qo&#39;llanma): wireframe tayyorlanadi → UI elementlari (rang, shrift, ikon) qo&#39;shiladi → tugma va linklar «bog&#39;lanadi» (masalan Figma Prototype rejimida) → foydalanuvchi bilan test qilinadi. Vositalar: Figma, Adobe XD, InVision, Sketch (keyingi haftalarda o&#39;tamiz; bugun dasturga hojat yo&#39;q). Nega wireframe avval? Xatoni boshida tuzatish arzon: qog&#39;ozda chizilgan xatoni ertasiga o&#39;chirish mumkin, tayyor ilovada esa oylar ketadi (qo&#39;llanmadagi «vaqt va pulni tejash» fikri).</p><h3 id="_2-6-foydalanuvchi-kim" tabindex="-1">2.6. Foydalanuvchi kim? <a class="header-anchor" href="#_2-6-foydalanuvchi-kim" aria-label="Permalink to &quot;2.6. Foydalanuvchi kim?&quot;">​</a></h3><p>UX «foydalanuvchi uchun qanchalik qulay?» degan savolga javob izlaydi, demak avval <strong>foydalanuvchi kimligini</strong> bilish kerak. Qo&#39;llanmadagi tushunchalar (ularning chuqur o&#39;tilishi 3-darsda):</p><ul><li><strong>Persona</strong> — foydalanuvchi kimligi (tipik, ideal foydalanuvchi portreti), uning maqsadi.</li><li><strong>Maqsad</strong> — u ilova bilan nimaga erishmoqchi.</li><li><strong>Kontekst</strong> — qayerda, qachon, qanday sharoitda foydalanadi; qiyinchiliklari («og&#39;riq nuqtalari»).</li><li><strong>Ssenariy</strong> — hikoya shaklidagi tasvir. Manbadagi misol: «Talaba Shaxnoza ilmiy maqola yozish uchun mobil ilovadan elektron kitob izlaydi. Kitob nomini qidiruvga kiritadi, kerakli kitobni tanlaydi, tafsilotini o&#39;qiydi va yuklab oladi.»</li><li><strong>User flow (foydalanuvchi oqimi)</strong> — maqsadga erishish yo&#39;li: ilovani ochish → qidiruv → natijadan tanlash → kitob sahifasi → yuklab olish. Shu ssenariydan funksional bloklar kelib chiqadi: qidiruv oynasi, kitoblar ro&#39;yxati, tafsilot sahifasi, yuklab olish tugmasi, xatcho&#39;p va baholash. Muhim fikr: «<strong>Men yoqtiraman</strong>» — dizayner mezoni emas; «<strong>foydalanuvchi qila oladimi?</strong>» — mezon.</li></ul>',21))]),i("div",b,[i("h2",k,[n(o,{name:"file-text"}),a[6]||(a[6]=t(" 3. Namuna materiallar (kod o'rniga) ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-namuna-materiallar-kod-o-rniga","aria-label":`Permalink to "<Icon name="file-text" /> 3. Namuna materiallar (kod o'rniga)"`},"​",-1))]),a[8]||(a[8]=r('<p>Bu darsda kod yo&#39;q. Mentor uchun tayyor ish varaqlari (doskaga yoki qog&#39;ozga):</p><p><strong>A. Mini-audit jadvali (o&#39;quvchi har bir ilova uchun to&#39;ldiradi):</strong></p><table tabindex="0"><thead><tr><th>Mezon</th><th>Ha / Yo&#39;q</th><th>Dalil (qaysi ekran, qaysi tugma)</th></tr></thead><tbody><tr><td>Control: xatoni qaytarish mumkinmi?</td><td></td><td></td></tr><tr><td>Consistency: tugmalar bir xilmi?</td><td></td><td></td></tr><tr><td>Comfortability: yozuv va masofa qulaymi?</td><td></td><td></td></tr><tr><td>Cognitive load: ekran ortiqcha yuklanmaganmi?</td><td></td><td></td></tr><tr><td>Feedback: bosganda javob bormi?</td><td></td><td></td></tr></tbody></table><p><strong>B. Qog&#39;oz wireframe qoidasi:</strong> telefon ramkasi (taxminan 6×12 sm), faqat to&#39;rtburchak va chiziq; rang, rasm va chiroyli yozuv yo&#39;q. Matn o&#39;rniga to&#39;lqinli chiziq, rasm o&#39;rniga kesishgan diagonalli to&#39;rtburchak.</p>',4))]),i("div",q,[i("h2",v,[n(o,{name:"file-text"}),a[9]||(a[9]=t(" 4. Amaliy topshiriqlar ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-amaliy-topshiriqlar","aria-label":'Permalink to "<Icon name="file-text" /> 4. Amaliy topshiriqlar"'},"​",-1))]),a[11]||(a[11]=r('<p>Hammasi qog&#39;ozda yoki daftarda bajariladi; o&#39;quvchi kompyuterda ham yoza oladi.</p><h3 id="oson-—-tamoyilni-topish-8-daqiqa" tabindex="-1">Oson — Tamoyilni topish (8 daqiqa) <a class="header-anchor" href="#oson-—-tamoyilni-topish-8-daqiqa" aria-label="Permalink to &quot;Oson — Tamoyilni topish (8 daqiqa)&quot;">​</a></h3><p>Beshta holat berilgan; har biri qaysi tamoyil buzilganini yoki bajarilganini ayting:</p><ol><li>Ilovada fotoni o&#39;chirdingiz, «Bekor qilish» tugmasi chiqdi.</li><li>Bir sahifada tugma ko&#39;k, boshqasida xuddi shu vazifa uchun qizil va boshqa shaklda.</li><li>«Yuborish» bosildi, lekin 5 soniya hech narsa o&#39;zgarmadi.</li><li>Bosh sahifada 14 ta banner, 9 ta tugma va 4 xil shrift.</li><li>Mayda yozuv va bir-biriga yopishgan tugmalar.</li></ol><p><strong>Kutiladigan natija:</strong> 5 ta to&#39;g&#39;ri juftlik (holat → tamoyil). <strong>Yechim:</strong> 1) Control (yaxshi); 2) Consistency (buzilgan); 3) Feedback (buzilgan); 4) Cognitive Load / Simplicity (buzilgan); 5) Comfortability (buzilgan).</p><h3 id="o-rta-—-ilova-auditi-20-daqiqa" tabindex="-1">O&#39;rta — Ilova auditi (20 daqiqa) <a class="header-anchor" href="#o-rta-—-ilova-auditi-20-daqiqa" aria-label="Permalink to &quot;O&#39;rta — Ilova auditi (20 daqiqa)&quot;">​</a></h3><p>O&#39;zingiz kunda ishlatadigan bitta ilova yoki saytni tanlang (Telegram, Instagram, maktab sayti va h.k.). 2.2-dagi «A» jadvalini to&#39;ldiring, kamida bitta kuchli va bitta zaif tomonni toping, bitta tuzatish taklif qiling.</p><p><strong>Kutiladigan natija:</strong> to&#39;ldirilgan jadval (5 qator, dalil bilan) va 2–3 jumla xulosa; rasm yoki skrinshot ixtiyoriy. <strong>Yechim namunasi:</strong> Telegram: Control: xabarni o&#39;chirganda «Hammada o&#39;chirish» tanlovi va xabarni tahrirlash bor (ha). Consistency: yuborish tugmasi har chatda bir xil (ha). Feedback: yuborilgan xabarda «bitta/ikki belgi» (ha). Zaif: sozlamalar ko&#39;p va chuqur joylashgan (Cognitive Load). Taklif: eng ko&#39;p ishlatiladigan sozlamalarni birinchi sahifaga chiqarish. (Mentor: o&#39;quvchi boshqa ilova tanlasa, mantiqiy dalil bo&#39;lsa — qabul qiling.)</p><h3 id="qiyin-—-yomon-ekranni-qayta-chizing-25-daqiqa" tabindex="-1">Qiyin — Yomon ekranni qayta chizing (25 daqiqa) <a class="header-anchor" href="#qiyin-—-yomon-ekranni-qayta-chizing-25-daqiqa" aria-label="Permalink to &quot;Qiyin — Yomon ekranni qayta chizing (25 daqiqa)&quot;">​</a></h3><p>Mentor doskaga yomon ekran tasvirlaydi: «Buyurtma» sahifasi: 10 ta bir xil tugma, mayda yozuv, «Buyurtma berish» tugmasi pastda yashiringan, bekor qilish yo&#39;q, bosilganda javob yo&#39;q. O&#39;quvchi: (1) kamida 4 ta muammoni yozadi va qaysi tamoyil buzilganini ko&#39;rsatadi; (2) qog&#39;ozda yaxshilangan <strong>wireframe</strong> chizadi (faqat to&#39;rtburchak va chiziq); (3) kamida 3 ta tamoyil qanday bajarilganini belgilaydi.</p><p><strong>Kutiladigan natija:</strong> muammolar ro&#39;yxati + 1 ta wireframe rasmi (qog&#39;oz yoki foto) + izohlar. <strong>Yechim namunasi:</strong> muammolar: Cognitive Load (10 ta bir xil tugma), Comfortability (mayda yozuv), Simplicity (asosiy harakat yashirin), Control (bekor qilish yo&#39;q), Feedback (javob yo&#39;q). Wireframe: tepada «Buyurtma» sarlavhasi; o&#39;rtada 3 qatorli mahsulot ro&#39;yxati; pastda katta, ajralib turuvchi «Buyurtma berish» tugmasi va kichik «Bekor qilish»; tugma bosilgach tasdiqlash xabari. Bonus: Design Thinking 5 bosqichidan qaysi biri bajarildi (Muammoni aniqlash va G&#39;oya).</p>',11))]),i("div",f,[i("h2",z,[n(o,{name:"file-text"}),a[12]||(a[12]=t(" 5. Tezkor nazorat ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#_5-tezkor-nazorat","aria-label":'Permalink to "<Icon name="file-text" /> 5. Tezkor nazorat"'},"​",-1))]),a[14]||(a[14]=r("<ol><li>UI ning 4C tamoyilini sanang. <em>(Control, Consistency, Comfortability, Cognitive Load.)</em></li><li>Feedback nima? Misol keltiring. <em>(Har amalga tizim javobi: tugma rangi o&#39;zgaradi, xabar chiqadi.)</em></li><li>Wireframe va prototip farqi nima? <em>(Wireframe — skelet, statik; prototip — bosiladigan, interaktiv model.)</em></li><li>Nega dizaynni avval qog&#39;ozda chizamiz? <em>(Xatoni boshida tuzatish arzon va tez.)</em></li><li>«Foydalanuvchi kim?» savoli nega birinchi? <em>(Dizayn uning ehtiyoji va maqsadi uchun qilinadi, bizniki uchun emas.)</em></li></ol>",1))]),i("div",c,[i("h2",p,[n(o,{name:"file-text"}),a[15]||(a[15]=t(" 6. Uyga vazifa ",-1)),a[16]||(a[16]=i("a",{class:"header-anchor",href:"#_6-uyga-vazifa","aria-label":'Permalink to "<Icon name="file-text" /> 6. Uyga vazifa"'},"​",-1))]),a[17]||(a[17]=i("p",null,[i("code",null,"uyga-vazifa.md"),t(" dagi 2-dars vazifasi (taxminan 20–30 daqiqa): bitta ilovaning 3 ta ekranini 4C bo'yicha baholash. Hafta vazifasi umumiy faylda; shu fayl boshqa agent tomonidan yoziladi.")],-1))]),i("div",x,[i("h2",_,[n(o,{name:"file-text"}),a[18]||(a[18]=t(" 7. Mentor uchun eslatmalar ",-1)),a[19]||(a[19]=i("a",{class:"header-anchor",href:"#_7-mentor-uchun-eslatmalar","aria-label":'Permalink to "<Icon name="file-text" /> 7. Mentor uchun eslatmalar"'},"​",-1))]),a[20]||(a[20]=i("ul",null,[i("li",null,"Manbada «yaxshi/yomon dizayn» ro'yxati va real mahsulot misollari kam (Google Maps, Mobile_Book, fitnes ilova, kiyim-kechak sayti, ijtimoiy tarmoq). Qolganlari tamoyillardan kelib chiqarilgan; Telegram/Instagram misollarini mentor «kuzatuv» deb bersin."),i("li",null,"4C va UX tamoyillarida «Consistency» ikki marta uchraydi: bu manbadagidek."),i("li",null,"Dasturiy ta'minot kerak emas; qog'oz, qalam va (ixtiyoriy) telefon ekrani yetadi."),i("li",null,"1-dars bilan takrorlanmaslik uchun UX/UI ta'rifi faqat 10 daqiqalik takrorlashda; asosiy vaqt tamoyil va jarayonga.")],-1))])])}const B=l(h,[["render",C]]);export{X as __pageData,B as default};
